package com.sigtm.backend.controller;
import com.sigtm.backend.dto.EstadoPresupuestoCompraResponse; import com.sigtm.backend.model.PresupuestoCompra; import com.sigtm.backend.service.PresupuestoCompraService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/presupuestos-compras") @RequiredArgsConstructor public class PresupuestoCompraController {private final PresupuestoCompraService service; @PostMapping @PreAuthorize("hasAuthority('COMPRAS:APROBAR')") public ResponseEntity<PresupuestoCompra> guardar(@Valid @RequestBody PresupuestoCompra p){return ResponseEntity.ok(service.guardar(p));} @GetMapping("/{periodo}") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<EstadoPresupuestoCompraResponse> estado(@PathVariable String periodo){return ResponseEntity.ok(service.estado(periodo));}}
